import { tags } from "typia";

import { IInvitationStatisticByRole } from "./IInvitationStatisticByRole";

/**
 * Aggregated employee invitation statistics for the current organization, providing comprehensive metrics on invitation counts, status distribution (pending, accepted, expired, revoked), recent invitation trends over 7, 14, and 30-day periods, and role-based breakdowns. All statistics exclude soft-deleted invitations and are scoped to the authenticated organization context.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IInvitationStatistic = {
  /**
   * Total number of employee invitations in the organization, excluding soft-deleted invitations.
   *
   * @x-autobe-specification COUNT(*) of all active invitations from hrm_platform_employee_invitations where organization_id matches current context AND deleted_at IS NULL.
   */
  total_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of invitations currently awaiting acceptance by invitees.
   *
   * @x-autobe-specification COUNT(*) from hrm_platform_employee_invitations WHERE status = 'pending' AND deleted_at IS NULL AND organization_id matches current context.
   */
  pending_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of invitations that have been successfully accepted and redeemed by invitees.
   *
   * @x-autobe-specification COUNT(*) from hrm_platform_employee_invitations WHERE status = 'accepted' AND deleted_at IS NULL AND organization_id matches current context.
   */
  accepted_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of invitations that have expired past their validity period without acceptance.
   *
   * @x-autobe-specification COUNT(*) from hrm_platform_employee_invitations WHERE status = 'expired' AND deleted_at IS NULL AND organization_id matches current context.
   */
  expired_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of invitations that were manually revoked before acceptance.
   *
   * @x-autobe-specification COUNT(*) from hrm_platform_employee_invitations WHERE status = 'revoked' AND deleted_at IS NULL AND organization_id matches current context.
   */
  revoked_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of invitations created in the last 7 days, indicating recent invitation activity.
   *
   * @x-autobe-specification COUNT(*) from hrm_platform_employee_invitations WHERE created_at >= NOW() - INTERVAL '7 days' AND deleted_at IS NULL AND organization_id matches current context.
   */
  trend_7_days: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of invitations created in the last 14 days, showing medium-term invitation trends.
   *
   * @x-autobe-specification COUNT(*) from hrm_platform_employee_invitations WHERE created_at >= NOW() - INTERVAL '14 days' AND deleted_at IS NULL AND organization_id matches current context.
   */
  trend_14_days: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of invitations created in the last 30 days, providing long-term invitation activity overview.
   *
   * @x-autobe-specification COUNT(*) from hrm_platform_employee_invitations WHERE created_at >= NOW() - INTERVAL '30 days' AND deleted_at IS NULL AND organization_id matches current context.
   */
  trend_30_days: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Breakdown of invitation counts grouped by the assigned role, showing how many invitations were sent for each role type in the organization.
   *
   * @x-autobe-specification GROUP BY hrm_platform_role_id from hrm_platform_employee_invitations WHERE deleted_at IS NULL AND organization_id matches current context. JOIN with hrm_platform_roles on hrm_platform_role_id = roles.id to retrieve role name. COUNT(*) per role to get invitation distribution by assigned role. Return as array of IInvitationStatisticByRole objects.
   */
  by_role: IInvitationStatisticByRole[];
};
